//! Host install slot, process-wide in production and thread-local in unit tests.

use super::backend::SecretBackend;
use std::sync::{Arc, RwLock};

#[cfg(not(test))]
fn slot() -> &'static RwLock<Option<Arc<dyn SecretBackend>>> {
    static SLOT: std::sync::OnceLock<RwLock<Option<Arc<dyn SecretBackend>>>> =
        std::sync::OnceLock::new();
    SLOT.get_or_init(|| RwLock::new(None))
}

#[cfg(test)]
fn slot() -> &'static RwLock<Option<Arc<dyn SecretBackend>>> {
    thread_local! {
        static SLOT: &'static RwLock<Option<Arc<dyn SecretBackend>>> =
            Box::leak(Box::new(RwLock::new(None)));
    }
    SLOT.with(|slot| *slot)
}

/// Install a host provider before core boot, replacing the previous provider.
pub fn install_secret_backend(provider: Arc<dyn SecretBackend>) {
    *slot().write().unwrap_or_else(|e| e.into_inner()) = Some(provider);
    super::reset_availability_cache();
}

/// The provider installed by the host, if any.
pub fn installed_secret_backend() -> Option<Arc<dyn SecretBackend>> {
    slot().read().unwrap_or_else(|e| e.into_inner()).clone()
}

/// Remove the installed provider. Call only while the core is stopped.
pub fn clear_secret_backend() {
    *slot().write().unwrap_or_else(|e| e.into_inner()) = None;
    super::reset_availability_cache();
}

use super::*;

#[test]
fn config_default_auto_approve_includes_expanded_tools() {
    // Issue #2486: verify read-only tools are auto-approved by default,
    // and write tools are NOT (Supervised mode must prompt for edits).
    // Explicitly enabled: the allowlist / risk gate this test is about only
    // exists when the policy is on, and the shipped config default is off.
    let cfg = crate::config::AutonomyConfig {
        enabled: true,
        ..crate::config::AutonomyConfig::default()
    };

    // Pre-existing auto-approved tools must still be present
    for tool in [
        "file_read",
        "memory_search",
        "memory_list",
        "get_time",
        "list_dir",
    ] {
        assert!(
            cfg.auto_approve.iter().any(|t| t == tool),
            "default auto_approve must still include pre-existing tool: {tool}"
        );
    }

    // Newly added read-only workspace-scoped tools
    for tool in ["glob", "grep"] {
        assert!(
            cfg.auto_approve.iter().any(|t| t == tool),
            "default auto_approve must include newly added tool: {tool}"
        );
    }

    // Write tools must NOT be auto-approved (v4→v5 migration strips these)
    for tool in ["file_write", "edit_file"] {
        assert!(
            !cfg.auto_approve.iter().any(|t| t == tool),
            "write tool {tool} must NOT be auto-approved by default"
        );
    }
}

// -- from_config --------------------------------------------------

#[test]
fn from_config_maps_all_fields() {
    let autonomy_config = crate::config::AutonomyConfig {
        level: AutonomyLevel::Full,
        workspace_only: false,
        allowed_commands: vec!["docker".into()],
        forbidden_paths: vec!["/secret".into()],
        max_actions_per_hour: 100,
        max_cost_per_day_cents: 1000,
        require_approval_for_medium_risk: false,
        block_high_risk_commands: false,
        auto_approve: vec!["shell".into(), "file_write".into()],
        ..crate::config::AutonomyConfig::default()
    };
    let workspace = PathBuf::from("/tmp/test-workspace");
    let policy = SecurityPolicy::from_config(&autonomy_config, &workspace, &workspace);

    assert_eq!(policy.autonomy, AutonomyLevel::Full);
    assert!(!policy.workspace_only);
    assert_eq!(policy.allowed_commands, vec!["docker"]);
    assert_eq!(policy.forbidden_paths, vec!["/secret"]);
    assert_eq!(policy.max_actions_per_hour, 100);
    assert_eq!(policy.max_cost_per_day_cents, 1000);
    assert!(!policy.require_approval_for_medium_risk);
    assert!(!policy.block_high_risk_commands);
    assert_eq!(policy.workspace_dir, PathBuf::from("/tmp/test-workspace"));
    // The "Always allow" allowlist is carried onto the policy so the gate can
    // skip prompting for these tools.
    assert_eq!(policy.auto_approve, vec!["shell", "file_write"]);
}

#[test]
fn policy_from_config_carries_auto_approve_all() {
    let workspace = PathBuf::from("/tmp/test-workspace");

    let enabled_config = crate::config::AutonomyConfig {
        auto_approve_all: true,
        ..crate::config::AutonomyConfig::default()
    };
    let enabled_policy = SecurityPolicy::from_config(&enabled_config, &workspace, &workspace);
    assert!(enabled_policy.auto_approve_all);

    let disabled_config = crate::config::AutonomyConfig {
        auto_approve_all: false,
        ..crate::config::AutonomyConfig::default()
    };
    let disabled_policy = SecurityPolicy::from_config(&disabled_config, &workspace, &workspace);
    assert!(!disabled_policy.auto_approve_all);
}

// -- Default policy -----------------------------------------------

#[test]
fn default_policy_has_sane_values() {
    let p = SecurityPolicy::default();
    assert_eq!(p.autonomy, AutonomyLevel::Supervised);
    assert!(p.workspace_only);
    assert!(!p.allowed_commands.is_empty());
    assert!(!p.forbidden_paths.is_empty());
    assert!(p.max_actions_per_hour > 0);
    assert!(p.max_cost_per_day_cents > 0);
    assert!(p.require_approval_for_medium_risk);
    assert!(p.block_high_risk_commands);
}

// -- ActionTracker / rate limiting --------------------------------

#[test]
fn action_tracker_starts_at_zero() {
    let tracker = ActionTracker::new();
    assert_eq!(tracker.count(), 0);
}

#[test]
fn action_tracker_records_actions() {
    let tracker = ActionTracker::new();
    assert_eq!(tracker.record(), 1);
    assert_eq!(tracker.record(), 2);
    assert_eq!(tracker.record(), 3);
    assert_eq!(tracker.count(), 3);
}

#[test]
fn record_action_allows_within_limit() {
    let p = SecurityPolicy {
        max_actions_per_hour: 5,
        ..SecurityPolicy::default()
    };
    for _ in 0..5 {
        assert!(p.record_action(), "should allow actions within limit");
    }
}

#[test]
fn record_action_blocks_over_limit() {
    let p = SecurityPolicy {
        max_actions_per_hour: 3,
        ..SecurityPolicy::default()
    };
    assert!(p.record_action()); // 1
    assert!(p.record_action()); // 2
    assert!(p.record_action()); // 3
    assert!(!p.record_action()); // 4 — over limit
}

#[test]
fn is_rate_limited_reflects_count() {
    let p = SecurityPolicy {
        max_actions_per_hour: 2,
        ..SecurityPolicy::default()
    };
    assert!(!p.is_rate_limited());
    p.record_action();
    assert!(!p.is_rate_limited());
    p.record_action();
    assert!(p.is_rate_limited());
}

#[test]
fn action_tracker_clone_is_independent() {
    let tracker = ActionTracker::new();
    tracker.record();
    tracker.record();
    let cloned = tracker.clone();
    assert_eq!(cloned.count(), 2);
    tracker.record();
    assert_eq!(tracker.count(), 3);
    assert_eq!(cloned.count(), 2); // clone is independent
}

// -- Edge cases: command injection --------------------------------

#[test]
fn command_injection_semicolon_blocked() {
    let p = default_policy();
    // First word is "ls;" (with semicolon) — doesn't match "ls" in allowlist.
    // This is a safe default: chained commands are blocked.
    assert!(!p.is_command_allowed("ls; rm -rf /"));
}

#[test]
fn command_injection_semicolon_no_space() {
    let p = default_policy();
    assert!(!p.is_command_allowed("ls;rm -rf /"));
}

#[test]
fn quoted_semicolons_do_not_split_sqlite_command() {
    let p = SecurityPolicy {
        allowed_commands: vec!["sqlite3".into()],
        ..SecurityPolicy::default()
    };
    assert!(p.is_command_allowed(
        "sqlite3 /tmp/test.db \"CREATE TABLE t(id INT); INSERT INTO t VALUES(1); SELECT * FROM t;\""
    ));
    assert_eq!(
        p.command_risk_level(
            "sqlite3 /tmp/test.db \"CREATE TABLE t(id INT); INSERT INTO t VALUES(1); SELECT * FROM t;\""
        ),
        CommandRiskLevel::Low
    );
}

#[test]
fn unquoted_semicolon_after_quoted_sql_still_splits_commands() {
    let p = SecurityPolicy {
        allowed_commands: vec!["sqlite3".into()],
        ..SecurityPolicy::default()
    };
    assert!(!p.is_command_allowed("sqlite3 /tmp/test.db \"SELECT 1;\"; rm -rf /"));
}

#[test]
fn command_injection_backtick_blocked() {
    let p = default_policy();
    assert!(!p.is_command_allowed("echo `whoami`"));
    assert!(!p.is_command_allowed("echo `rm -rf /`"));
}

#[test]
fn command_injection_dollar_paren_blocked() {
    let p = default_policy();
    assert!(!p.is_command_allowed("echo $(cat /etc/passwd)"));
    assert!(!p.is_command_allowed("echo $(rm -rf /)"));
}

#[test]
fn command_with_env_var_prefix() {
    let p = default_policy();
    // "FOO=bar" is the first word — not in allowlist
    assert!(!p.is_command_allowed("FOO=bar rm -rf /"));
}

#[test]
fn command_newline_injection_blocked() {
    let p = default_policy();
    // Newline splits into two commands; "rm" is not in allowlist
    assert!(!p.is_command_allowed("ls\nrm -rf /"));
    // Both allowed — OK
    assert!(p.is_command_allowed("ls\necho hello"));
}

#[test]
fn command_injection_and_chain_blocked() {
    let p = default_policy();
    assert!(!p.is_command_allowed("ls && rm -rf /"));
    assert!(!p.is_command_allowed("echo ok && curl http://evil.com"));
    // Both allowed — OK
    assert!(p.is_command_allowed("ls && echo done"));
}

#[test]
fn command_injection_or_chain_blocked() {
    let p = default_policy();
    assert!(!p.is_command_allowed("ls || rm -rf /"));
    // Both allowed — OK
    assert!(p.is_command_allowed("ls || echo fallback"));
}

//! The configured `action_dir` as a granted read-write trusted root.
//!
//! Split out of `policy_trusted_roots_tests.rs` only for file size; the subject
//! is the same grant, and the fixtures there deliberately set
//! `action_dir == workspace_dir`, which is exactly the shape that hid this.

use super::*;
use std::fs;

/// The configured `action_dir` must be a read-write trusted root.
///
/// It is the base `validate_path` joins every relative tool path onto, but it
/// was never itself an allow root: the write permission came from the
/// `default_projects_dir()` grant above, which reads `OPENHUMAN_PROJECTS_DIR`
/// and knows nothing about `OPENHUMAN_ACTION_DIR` / `action_dir_override`. On a
/// stock install the two coincide, which is why every existing fixture in this
/// file (`action_dir == workspace_dir`) missed it. Point them apart — which is
/// what the Settings working-folder control does — and a write into the
/// agent's own working directory was refused "Resolved path escapes
/// workspace".
#[test]
fn from_config_grants_the_configured_action_dir_as_readwrite_root() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let workspace = tmp.path().join("workspace");
    let action = tmp.path().join("elsewhere/action");
    fs::create_dir_all(&workspace).unwrap();
    fs::create_dir_all(&action).unwrap();

    let cfg = crate::config::AutonomyConfig::default();
    let policy = SecurityPolicy::from_config(&cfg, &workspace, &action);
    let action_str = action.to_string_lossy().to_string();
    assert!(
        policy
            .trusted_roots
            .iter()
            .any(|r| r.path == action_str && matches!(r.access, TrustedAccess::ReadWrite)),
        "from_config must grant the action dir as read-write; got: {:?}",
        policy.trusted_roots
    );
}

/// The grant must reach the gate every file write funnels through, not just the
/// `trusted_roots` vector. Built with the policy explicitly enabled, since the
/// containment this proves is exactly what `enabled = false` turns off.
#[tokio::test]
async fn an_enabled_policy_can_write_into_its_action_dir_outside_the_workspace() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let workspace = tmp.path().join("workspace");
    let action = tmp.path().join("elsewhere/action");
    fs::create_dir_all(&workspace).unwrap();
    fs::create_dir_all(action.join("out")).unwrap();

    let cfg = crate::config::AutonomyConfig {
        enabled: true,
        ..crate::config::AutonomyConfig::default()
    };
    let policy = SecurityPolicy::from_config(&cfg, &workspace, &action);
    let resolved = policy
        .validate_parent_path("out/plan.md")
        .await
        .expect("a relative write into the action dir must be permitted");
    assert!(resolved.ends_with("out/plan.md"), "got {resolved:?}");
}

/// An action dir at or above `workspace_dir` is NOT granted: a trusted root
/// there would hand the whole workspace a `forbidden_paths` bypass
/// (`check_resolved_against_forbidden` returns early for a trusted root).
#[test]
fn from_config_does_not_grant_an_action_dir_covering_the_workspace() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let action = tmp.path().to_path_buf();
    let workspace = action.join("workspace");
    fs::create_dir_all(&workspace).unwrap();

    let cfg = crate::config::AutonomyConfig::default();
    let policy = SecurityPolicy::from_config(&cfg, &workspace, &action);
    let action_str = action.to_string_lossy().to_string();
    assert!(
        !policy.trusted_roots.iter().any(|r| r.path == action_str),
        "an action dir above the workspace must not be granted; got: {:?}",
        policy.trusted_roots
    );
}

/// Oversized tool outputs are saved under `<workspace>/artifacts/tool-results`
/// and pointed at by absolute path. Under `workspace_only` an absolute path is
/// refused unless a trusted root covers it, so `from_config` grants that one
/// directory — read-only — and nothing else under the workspace.
#[tokio::test]
async fn tool_result_artifacts_are_readable_by_absolute_path_under_workspace_only() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let workspace = tmp.path().join("workspace");
    let action = tmp.path().join("project");
    let artifacts = super::tool_result_artifacts_dir(&workspace).join("s1/shell");
    fs::create_dir_all(&artifacts).unwrap();
    fs::create_dir_all(&action).unwrap();
    fs::write(artifacts.join("call.txt"), "output").unwrap();
    let record = workspace.join("artifacts/abc");
    fs::create_dir_all(&record).unwrap();
    fs::write(record.join("meta.json"), "{}").unwrap();

    let cfg = crate::config::AutonomyConfig {
        enabled: true,
        workspace_only: true,
        ..crate::config::AutonomyConfig::default()
    };
    let policy = SecurityPolicy::from_config(&cfg, &workspace, &action);

    let grant = super::tool_result_artifacts_dir(&workspace)
        .to_string_lossy()
        .to_string();
    assert!(policy
        .trusted_roots
        .iter()
        .any(|r| r.path == grant && r.access == TrustedAccess::Read));

    let result = artifacts.join("call.txt");
    policy
        .validate_path(&result.to_string_lossy())
        .await
        .expect("a tool-result artifact must be readable by absolute path");
    // The grant is that directory only: internal artifact records stay closed.
    assert!(policy
        .validate_path(&record.join("meta.json").to_string_lossy())
        .await
        .is_err());
}

import { expect, it } from 'vitest';

// @ts-ignore - test-only JS module outside app/src
import { clearRequestLog, getMockServerPort } from '../../../scripts/mock-api-core.mjs';

it('redacts sensitive request headers in the mock API log', async () => {
  clearRequestLog();

  const mockApiUrl = `http://127.0.0.1:${getMockServerPort()}`;
  await fetch(`${mockApiUrl}/__admin/health`, {
    headers: {
      Authorization: 'Bearer secret-token',
      'Proxy-Authorization': 'Basic secret-token',
      'X-Test-Version': '1.2.3',
    },
  });

  const requestsResponse = await fetch(`${mockApiUrl}/__admin/requests`);
  const requestsPayload = (await requestsResponse.json()) as {
    data?: Array<{ headers?: Record<string, string> }>;
  };
  const request = requestsPayload.data?.find(
    entry => entry.headers?.['x-test-version'] === '1.2.3'
  );
  expect(request?.headers).toMatchObject({
    authorization: '[REDACTED]',
    'proxy-authorization': '[REDACTED]',
    'x-test-version': '1.2.3',
  });
});

