use super::*;

#[tokio::test]
async fn prepare_messages_rejects_too_many_images() {
    let messages = vec![TranscriptMessage::user(
        "[IMAGE:/tmp/1.png]\n[IMAGE:/tmp/2.png]".to_string(),
    )];

    let config = MultimodalConfig {
        max_images: 1,
        max_image_size_mb: 5,
        allow_remote_fetch: false,
    };

    let error = prepare_messages_for_provider(&messages, &config, &MultimodalFileConfig::default())
        .await
        .expect_err("should reject image count overflow");

    assert!(error
        .to_string()
        .contains("multimodal image limit exceeded"));
}

#[tokio::test]
async fn prepare_messages_extracts_text_from_pdf() {
    let temp = tempfile::tempdir().unwrap();
    let file_path = temp.path().join("doc.pdf");
    std::fs::write(&file_path, SAMPLE_PDF_BYTES).unwrap();

    let messages = vec![TranscriptMessage::user(format!(
        "[FILE:{}]",
        file_path.display()
    ))];
    let prepared = prepare_messages_for_provider(
        &messages,
        &MultimodalConfig::default(),
        &MultimodalFileConfig::default(),
    )
    .await
    .unwrap();
    let body = &prepared.messages[0].content;
    // Tolerant: pdf-extract may emit a Reference fallback if it cannot
    // walk this hand-rolled skeleton on every host. Either path proves
    // the PDF passed the size/MIME gates and was routed through the
    // extraction branch — the agent always learns the file exists.
    assert!(
        body.contains("[FILE-EXTRACTED:") || body.contains("[FILE-ATTACHED:"),
        "expected a file block, got: {body}"
    );
    assert!(body.contains("application/pdf"));
}

#[tokio::test]
async fn prepare_messages_rejects_oversized_file() {
    let temp = tempfile::tempdir().unwrap();
    let file_path = temp.path().join("huge.txt");
    std::fs::write(&file_path, vec![b'a'; 2 * 1024 * 1024]).unwrap();

    let messages = vec![TranscriptMessage::user(format!(
        "[FILE:{}]",
        file_path.display()
    ))];
    let file_config = MultimodalFileConfig {
        max_file_size_mb: 1,
        ..Default::default()
    };

    let err = prepare_messages_for_provider(&messages, &MultimodalConfig::default(), &file_config)
        .await
        .expect_err("oversized file must be rejected");

    assert!(err
        .to_string()
        .contains("multimodal file size limit exceeded"));
}

import { expect, test } from '@playwright/test';

import {
  bootAuthenticatedPage,
  dismissWalkthroughIfPresent,
  waitForAppReady,
} from '../helpers/core-rpc';

/**
 * The Skills explorer's search and install affordances, driven in a real
 * browser.
 *
 * `skills-registry.spec.ts` has a test called "search filters entries by query",
 * but it lives in that file's `Skill registry RPC smoke` describe — it calls
 * `openhuman.skill_registry_search` directly and never touches the UI. Nothing
 * types into the search box, and nothing exercises the install button.
 *
 * The part that only a browser can check is the **debounce**:
 * `SkillsExplorerTab.tsx:22` sets `SEARCH_DEBOUNCE_MS = 300` and `:469-478`
 * restarts the timer on every keystroke, so a burst of typing must produce ONE
 * catalog search rather than one per character. Counting real RPCs against real
 * keystroke timing is not something jsdom reproduces faithfully.
 *
 * NOTE ON SCOPE: this uses `?tab=skills`, never the Composio tab. Opening that
 * one downloads the `tinyconnectors` module from a GitHub release and a failed
 * download is terminal for the core process — see W3-ui-bugs.md §3.
 */

const SEARCH = 'skill-search-input';

async function openSkillsTab(page: import('@playwright/test').Page, userId: string) {
  // The Skills surface asks for Composio's curated-toolkit labels while it
  // mounts. That native connector bootstrap is unrelated to local catalog
  // search/install behavior and can fault the standalone test core, obscuring
  // this spec's actual browser contract.
  await page.route('**/rpc', async (route, request) => {
    try {
      const body = JSON.parse(request.postData() || '{}');
      if (body.method === 'openhuman.composio_list_agent_ready_toolkits') {
        await route.fulfill({
          contentType: 'application/json',
          body: JSON.stringify({
            jsonrpc: '2.0',
            id: body.id,
            result: { result: { toolkits: [] }, logs: [] },
          }),
        });
        return;
      }
    } catch {
      // Let malformed or unrelated RPCs reach the real core.
    }
    await route.continue();
  });
  // `signInViaBypassUser` intentionally settles on the chat landing route.
  // Use the authenticated-route helper so its post-auth shell restoration
  // cannot overwrite this spec's Connections deep link.
  await bootAuthenticatedPage(page, userId, '/connections?tab=skills');
  await expect
    .poll(() => page.evaluate(() => window.location.hash), { timeout: 15_000 })
    .toContain('tab=skills');
  await waitForAppReady(page);
  await dismissWalkthroughIfPresent(page);
  await page.getByTestId('skill-explorer-tab-registry').click();
  await expect(page.getByTestId(SEARCH)).toBeVisible({ timeout: 20_000 });
}

/** Count `skill_registry_search` RPCs, letting everything through untouched. */
async function countSearchRpcs(page: import('@playwright/test').Page) {
  const queries: string[] = [];
  await page.route('**/rpc', async (route, request) => {
    try {
      const body = JSON.parse(request.postData() || '{}');
      if (body.method === 'openhuman.skill_registry_search') {
        queries.push(String(body.params?.query ?? ''));
      }
    } catch {
      /* not JSON — pass it through untouched */
    }
    await route.continue();
  });
  return queries;
}

const searchBox = (page: import('@playwright/test').Page) => page.getByTestId(SEARCH);

test.describe('Skills explorer — the search box debounces', () => {
  test('a burst of typing issues ONE catalog search, not one per keystroke', async ({ page }) => {
    await openSkillsTab(page, 'pw-skills-debounce');
    const queries = await countSearchRpcs(page);

    // Type well inside the 300 ms window. Playwright's default `type` delay is
    // 0, so these land in a few milliseconds of each other.
    await searchBox(page).type('docker', { delay: 20 });

    // Wait past the debounce and let the request settle.
    await expect.poll(() => queries.length, { timeout: 10_000 }).toBeGreaterThan(0);
    await page.waitForTimeout(600);

    expect(
      queries.length,
      `expected one debounced search, got ${queries.length}: ${JSON.stringify(queries)}`
    ).toBe(1);
    // And the one that fired carries the FINAL text, not a prefix.
    expect(queries[0]).toBe('docker');
  });

  test('a pause between words issues a second search', async ({ page }) => {
    // The mirror of the test above: the debounce must delay, not swallow.
    await openSkillsTab(page, 'pw-skills-debounce-two');
    const queries = await countSearchRpcs(page);

    await searchBox(page).type('git', { delay: 20 });
    await expect.poll(() => queries.length, { timeout: 10_000 }).toBe(1);

    await searchBox(page).type('hub', { delay: 20 });
    await expect.poll(() => queries.length, { timeout: 10_000 }).toBe(2);
    expect(queries[1]).toBe('github');
  });
});

test.describe('Skills explorer — typing narrows what is on screen', () => {
  test('a query with no matches leaves no catalog rows', async ({ page }) => {
    const entry = {
      id: 'fixture-skill',
      name: 'Fixture skill',
      description: 'A deterministic catalog fixture.',
      source: 'fixture',
      category: 'testing',
      author: null,
      version: null,
      tags: [],
      platforms: [],
      download_url: 'https://example.invalid/fixture',
      docs_path: null,
      commands: [],
      env_vars: [],
      license: null,
    };
    await page.route('**/rpc', async (route, request) => {
      const body = JSON.parse(request.postData() || '{}');
      if (
        !['openhuman.skill_registry_browse', 'openhuman.skill_registry_search'].includes(
          body.method
        )
      ) {
        await route.continue();
        return;
      }
      const entries = body.params?.query ? [] : [entry];
      await route.fulfill({
        contentType: 'application/json',
        body: JSON.stringify({ jsonrpc: '2.0', id: body.id, result: { entries } }),
      });
    });
    await openSkillsTab(page, 'pw-skills-nomatch');

    const rows = page.locator('[data-testid^="registry-install-"]');
    await expect(rows.first()).toBeVisible();

    await searchBox(page).fill('zzzz-no-such-skill-zzzz');
    // Any install button is a catalog row; none should survive this query.
    await expect(rows).toHaveCount(0, { timeout: 15_000 });

    // NOT asserted: that clearing the box restores the rows. Clearing takes the
    // `!query && !sourceFilter` branch of `fetchCatalog`
    // (SkillsExplorerTab.tsx:517), which calls `skillRegistryApi.browse()` — an
    // UPSTREAM registry fetch. In this lane that is not reliably fast, and an
    // earlier draft asserting it passed alone and failed in a full five-spec
    // run. A flaky assertion is not an improvement on the vacuous one it
    // replaced, so this test pins only the deterministic half: the query
    // empties the list.
  });

  test('the typed text is preserved in the box while results load', async ({ page }) => {
    // A search box that clears itself mid-request loses what the user typed.
    //
    // The search RPC is HELD so the assertion lands while the request is
    // genuinely outstanding. The earlier form typed, slept 800ms and asserted —
    // which proves the value survives a fixed delay, not that it survives a
    // request in flight. By 800ms the search may already have completed, in
    // which case the test says nothing about the "while results load" case its
    // own name claims. Caught in review by `coderabbitai`.
    let releaseSearch!: () => void;
    const searchHeld = new Promise<void>(resolve => {
      releaseSearch = resolve;
    });
    let searchStarted = false;

    await openSkillsTab(page, 'pw-skills-preserve');

    await page.route('**/rpc', async (route, request) => {
      let method = '';
      try {
        method = JSON.parse(request.postData() || '{}').method ?? '';
      } catch {
        /* pass through */
      }
      if (method === 'openhuman.skill_registry_search') {
        searchStarted = true;
        await searchHeld;
      }
      await route.continue();
    });

    await searchBox(page).fill('docker');

    // Wait for the request to actually be in flight, then assert.
    await expect.poll(() => searchStarted, { timeout: 15_000 }).toBe(true);
    await expect(searchBox(page)).toHaveValue('docker');

    releaseSearch();
  });
});

test.describe('Skills explorer — the install button', () => {
  /** Find the first catalog row offering an install. */
  async function firstInstallButton(page: import('@playwright/test').Page) {
    const button = page.locator('[data-testid^="registry-install-"]').first();
    await expect(button).toBeVisible({ timeout: 20_000 });
    const testId = await button.getAttribute('data-testid');
    expect(testId).toBeTruthy();
    return page.getByTestId(testId!);
  }

  test('offers Install, and the button is enabled before it is pressed', async ({ page }) => {
    await openSkillsTab(page, 'pw-skills-install-idle');
    const button = await firstInstallButton(page);

    await expect(button).toBeEnabled();
    await expect(button).toHaveText(/install/i);
  });

  test('disables the button and shows Installing while the RPC is in flight', async ({ page }) => {
    // The transition only exists while the request is outstanding, so the
    // install RPC is held open deliberately. This is the state a jsdom test
    // cannot observe without faking timers.
    let release!: () => void;
    const held = new Promise<void>(resolve => {
      release = resolve;
    });

    await openSkillsTab(page, 'pw-skills-install-inflight');
    const button = await firstInstallButton(page);

    await page.route('**/rpc', async (route, request) => {
      let method = '';
      try {
        method = JSON.parse(request.postData() || '{}').method ?? '';
      } catch {
        /* pass through */
      }
      if (method === 'openhuman.skill_registry_install') {
        await held;
      }
      await route.continue();
    });

    await button.click();

    await expect(button).toBeDisabled({ timeout: 10_000 });
    await expect(button).toHaveText(/installing/i);

    release();
  });

  test('a failed install re-enables the button rather than stranding it', async ({ page }) => {
    // If the button stayed disabled on failure the user could not retry, and
    // nothing on screen would say why.
    //
    // The install response is HELD rather than answered immediately. Without
    // that, "enabled and reading Install" is also the button's INITIAL state,
    // so the test passed whether or not the click ever did anything — it could
    // not distinguish recovery from a no-op. Holding lets us prove the round
    // trip: enabled -> (held) disabled/Installing -> released -> enabled again.
    // Caught in review by `coderabbitai`.
    let releaseInstall!: () => void;
    const installHeld = new Promise<void>(resolve => {
      releaseInstall = resolve;
    });
    let installBody: { id?: unknown } = {};

    await openSkillsTab(page, 'pw-skills-install-fail');
    const button = await firstInstallButton(page);
    await expect(button).toBeEnabled();

    await page.route('**/rpc', async (route, request) => {
      let body: { method?: string; id?: unknown } = {};
      try {
        body = JSON.parse(request.postData() || '{}');
      } catch {
        /* pass through */
      }
      if (body.method === 'openhuman.skill_registry_install') {
        installBody = body;
        await installHeld;
        await route.fulfill({
          status: 200,
          contentType: 'application/json',
          body: JSON.stringify({
            jsonrpc: '2.0',
            id: installBody.id,
            error: { code: -32000, message: 'install refused by the registry' },
          }),
        });
        return;
      }
      await route.continue();
    });

    await button.click();

    // The pending state must actually be reached before the failure.
    await expect(button).toBeDisabled({ timeout: 15_000 });
    await expect(button).toHaveText(/installing/i);

    releaseInstall();

    await expect(button).toBeEnabled({ timeout: 20_000 });
    await expect(button).toHaveText(/install/i);
  });
});

import { describe, expect, it } from 'vitest';

import {
  evaluateComposerSend,
  getComposerBlockedSendFeedback,
  handleComposerSlashCommand,
  shouldSendComposerKeyDown,
} from './composerSendDecision';

describe('evaluateComposerSend', () => {
  it('blocks empty input', () => {
    const decision = evaluateComposerSend({
      rawText: '   ',
      selectedThreadId: 'thread-1',
      composerInteractionBlocked: false,
      isAtLimit: false,
      socketStatus: 'connected',
    });

    expect(decision).toEqual({ shouldSend: false, trimmedText: '', blockReason: 'empty_input' });
  });

  it('blocks usage limit', () => {
    const decision = evaluateComposerSend({
      rawText: 'hello',
      selectedThreadId: 'thread-1',
      composerInteractionBlocked: false,
      isAtLimit: true,
      socketStatus: 'connected',
    });

    expect(decision.blockReason).toBe('usage_limit_reached');
    expect(decision.shouldSend).toBe(false);
  });

  it('blocks when no thread is selected', () => {
    const decision = evaluateComposerSend({
      rawText: 'hello',
      selectedThreadId: null,
      composerInteractionBlocked: false,
      isAtLimit: false,
      socketStatus: 'connected',
    });

    expect(decision.blockReason).toBe('missing_thread');
    expect(decision.shouldSend).toBe(false);
  });

  it('blocks while composer interaction is disabled', () => {
    const decision = evaluateComposerSend({
      rawText: 'hello',
      selectedThreadId: 'thread-1',
      composerInteractionBlocked: true,
      isAtLimit: false,
      socketStatus: 'connected',
    });

    expect(decision.blockReason).toBe('composer_blocked');
    expect(decision.shouldSend).toBe(false);
  });

  it('blocks when socket is disconnected', () => {
    const decision = evaluateComposerSend({
      rawText: 'hello',
      selectedThreadId: 'thread-1',
      composerInteractionBlocked: false,
      isAtLimit: false,
      socketStatus: 'disconnected',
    });

    expect(decision.blockReason).toBe('socket_disconnected');
    expect(decision.shouldSend).toBe(false);
  });

  it('allows send path setup for valid chat send input', () => {
    const decision = evaluateComposerSend({
      rawText: ' hello ',
      selectedThreadId: 'thread-1',
      composerInteractionBlocked: false,
      isAtLimit: false,
      socketStatus: 'connected',
    });

    expect(decision).toEqual({ shouldSend: true, trimmedText: 'hello' });
  });
});

describe('handleComposerSlashCommand', () => {
  it('consumes /new command', () => {
    expect(handleComposerSlashCommand('/new')).toEqual({ kind: 'new_or_clear' });
  });

  it('consumes /clear command (case-insensitive)', () => {
    expect(handleComposerSlashCommand('/CLEAR')).toEqual({ kind: 'new_or_clear' });
  });

  it('ignores normal chat text', () => {
    expect(handleComposerSlashCommand('hello')).toEqual({ kind: 'not_handled' });
  });

  it('maps /plan and /build to a run-mode switch', () => {
    expect(handleComposerSlashCommand('/plan')).toEqual({ kind: 'run_mode', mode: 'plan' });
    expect(handleComposerSlashCommand('/Build')).toEqual({ kind: 'run_mode', mode: 'build' });
  });

  it('maps /stop to cancelling the running turn', () => {
    expect(handleComposerSlashCommand('/stop')).toEqual({ kind: 'stop' });
  });

  it('does not treat a command followed by prose as the command', () => {
    expect(handleComposerSlashCommand('/plan the migration')).toEqual({ kind: 'not_handled' });
  });
});

describe('shouldSendComposerKeyDown', () => {
  it('allows Enter to send when IME composition is inactive', () => {
    expect(shouldSendComposerKeyDown({ key: 'Enter' })).toBe(true);
  });

  it('does not send on Shift+Enter', () => {
    expect(shouldSendComposerKeyDown({ key: 'Enter', shiftKey: true })).toBe(false);
  });

  it('does not send while React reports IME composition', () => {
    expect(shouldSendComposerKeyDown({ key: 'Enter', nativeEvent: { isComposing: true } })).toBe(
      false
    );
  });

  it('does not send while the browser reports legacy IME keyCode 229', () => {
    expect(shouldSendComposerKeyDown({ key: 'Enter', nativeEvent: { keyCode: 229 } })).toBe(false);
  });

  it('does not send while textarea composition state is active', () => {
    expect(shouldSendComposerKeyDown({ key: 'Enter' }, true)).toBe(false);
  });
});

describe('getComposerBlockedSendFeedback', () => {
  it('returns error feedback for usage-limit blocking', () => {
    expect(getComposerBlockedSendFeedback('usage_limit_reached')).toEqual({
      error: {
        code: 'usage_limit_reached',
        message: 'Included budget exhausted. Top up credits or upgrade to continue.',
      },
    });
  });

  it('returns send error feedback for socket-disconnected blocking', () => {
    expect(getComposerBlockedSendFeedback('socket_disconnected')).toEqual({
      error: {
        code: 'socket_disconnected',
        message:
          'Realtime socket is not connected — responses cannot be delivered without a client ID.',
      },
    });
  });

  it('ignores block reasons that do not surface user feedback', () => {
    expect(getComposerBlockedSendFeedback('empty_input')).toBeNull();
    expect(getComposerBlockedSendFeedback(undefined)).toBeNull();
  });
});

use super::*;

/// A config rooted in a throwaway directory.
///
/// Non-negotiable for these tests: `IdentitySection` calls
/// `sync_workspace_file`, which **writes** `SOUL.md` / `IDENTITY.md` /
/// `ROLE.md` into `workspace_dir`. Composing against
/// `Config::default()` would scribble into the developer's real
/// `~/.openhuman` workspace.
fn config_in(dir: &std::path::Path) -> Arc<Config> {
    let mut config = Config::default();
    config.workspace_dir = dir.to_path_buf();
    config.action_dir = dir.join("projects");
    std::fs::create_dir_all(&config.action_dir).expect("create action dir");
    Arc::new(config)
}

fn request() -> TurnContextRequest {
    TurnContextRequest::new("orchestrator", "thread-1", "what changed today?")
}

#[tokio::test]
async fn composes_a_non_empty_prompt_carrying_the_agent_id() {
    let dir = tempfile::tempdir().expect("tempdir");
    let composer = OpenHumanContextComposer::new(config_in(dir.path()));
    let prompt = composer
        .compose_system_prompt(&request())
        .await
        .expect("prompt composes");

    assert!(!prompt.trim().is_empty(), "prompt must not be blank");
    // The default chain always appends the grounding contract and the
    // global style suffix; asserting on the suffix pins that we went
    // through `SystemPromptBuilder::build` rather than hand-assembling.
    assert!(
        prompt.contains("# Writing style"),
        "prompt must come from SystemPromptBuilder::build"
    );
}

#[tokio::test]
async fn preamble_is_empty_and_not_an_error() {
    let dir = tempfile::tempdir().expect("tempdir");
    let composer = OpenHumanContextComposer::new(config_in(dir.path()));
    assert!(composer
        .preamble(&request())
        .await
        .expect("preamble succeeds")
        .is_empty());
}

#[tokio::test]
async fn the_prompt_is_byte_stable_across_repeated_turns() {
    // The KV-cache contract from mismatch (1): the crate calls this every
    // turn, and OpenHuman needs the bytes frozen. `DateTimeSection` has
    // minute granularity, so two back-to-back calls agreeing is the
    // strongest cheap check that nothing *else* varies per call.
    let dir = tempfile::tempdir().expect("tempdir");
    let composer = OpenHumanContextComposer::new(config_in(dir.path()));
    let a = composer
        .compose_system_prompt(&request())
        .await
        .expect("first");
    let b = composer
        .compose_system_prompt(&request())
        .await
        .expect("second");
    assert_eq!(a, b);
}

#[tokio::test]
async fn a_different_agent_id_still_composes() {
    // The crate treats `agent_id` as opaque, so an id the host has never
    // heard of must not fail composition — it is a prompt input, not a
    // registry lookup.
    let dir = tempfile::tempdir().expect("tempdir");
    let composer = OpenHumanContextComposer::new(config_in(dir.path()));
    let req = TurnContextRequest::new("no-such-agent", "thread-9", "");
    assert!(composer.compose_system_prompt(&req).await.is_ok());
}

#[test]
fn agents_md_layers_are_loaded_when_the_gate_is_on() {
    let dir = tempfile::tempdir().expect("tempdir");
    let config = config_in(dir.path());
    std::fs::write(dir.path().join("AGENTS.md"), "global rule").expect("write global");

    let composer = OpenHumanContextComposer::new(config);
    let loaded = composer.agents_md();
    assert_eq!(loaded.global.as_deref(), Some("global rule"));
}

#[test]
fn the_agents_md_gate_is_honoured_when_off() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = Config::default();
    config.workspace_dir = dir.path().to_path_buf();
    config.action_dir = dir.path().join("projects");
    config.agent.agents_md_enabled = false;
    std::fs::create_dir_all(&config.action_dir).expect("create action dir");
    std::fs::write(dir.path().join("AGENTS.md"), "global rule").expect("write global");

    let composer = OpenHumanContextComposer::new(Arc::new(config));
    let loaded = composer.agents_md();
    assert!(
        loaded.is_empty(),
        "a disabled gate must not read AGENTS.md at all"
    );
}

#[test]
fn the_model_name_falls_back_to_the_crate_default() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = Config::default();
    config.workspace_dir = dir.path().to_path_buf();
    config.default_model = None;
    let composer = OpenHumanContextComposer::new(Arc::new(config));
    assert_eq!(composer.model_name, DEFAULT_MODEL);

    let pinned = OpenHumanContextComposer::new(config_in(dir.path())).with_model_name("haiku");
    assert_eq!(pinned.model_name, "haiku");
}

import { act, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
